export const grammar={
 be:['am / is / are','Use am with I, is with he, she and it, and are with you, we and they.',rows('I ___ a new student.~am~is~are|Her name ___ Anna.~is~am~are|We ___ in the same class.~are~is~am|They ___ from London.~are~am~is|___ you our new teacher?~Are~Is~Am|He ___ not at school today.~is~are~am')],
 have:['have / has','Use have with I, you, we and they. Use has with he, she and it.',rows('Leo ___ one sister.~has~have~having|I ___ two cousins.~have~has~having|My parents ___ a pet cat.~have~has~having|Sara ___ a small family.~has~have~haves|We do not ___ a dog.~have~has~having|Does Max ___ a brother?~have~has~having')],
 simple:['Present Simple','Use the present simple for routines. Add s with he, she and it. Use do or does in questions.',rows('Nora ___ to school every day.~walks~walk~walking|I ___ breakfast at seven.~have~has~having|She does not ___ on Sundays.~study~studies~studying|___ your lessons start at nine?~Do~Does~Is|My brother ___ books after school.~reads~read~reading|What time ___ she get up?~does~do~is')],
 there:['there is / there are','Use there is for one thing and there are for more than one thing.',rows('There ___ a desk near the window.~is~are~am|There ___ two bedrooms in our flat.~are~is~am|___ there a garden behind the house?~Is~Are~Am|There ___ not any chairs in the kitchen.~are~is~am|The bag is ___ the desk, on the floor.~under~into~through|There ___ one key on the table.~is~are~be')],
 some:['some / any','Use some in positive sentences. Use any in most questions and negative sentences. A and an are used with singular countable nouns.',rows('There is ___ apple on the table.~an~a~any|We have ___ bread for lunch.~some~a~an|Is there ___ milk in the fridge?~any~a~an|I would like ___ sandwich.~a~an~any|There is not ___ cake today.~any~a~an|She drinks ___ water every morning.~some~an~a')],
 can:['can / cannot','Use can for ability or permission. The verb after can stays in its base form.',rows('You can ___ a ticket at the museum.~buy~buys~buying|___ you help me, please?~Can~Do can~Are can|He cannot ___ the station.~find~finds~finding|We ___ speak English in class.~can~cans~to can|Can she ___ a map?~read~reads~reading|They can ___ the road here.~cross~crosses~crossing')],
 continuous:['Present Continuous','Use am, is or are plus the ing form to describe something happening now.',rows('Lily ___ waiting for the bus now.~is~are~am|Her brother is ___ a game.~playing~play~plays|I ___ wearing a blue coat today.~am~is~are|They ___ not studying right now.~are~is~am|___ she making tea?~Is~Does~Do|Look! The children are ___.~running~run~runs')],
 'past-be':['was / were','Use was with I, he, she and it. Use were with you, we and they to talk about the past.',rows('Ali ___ in a village last weekend.~was~were~is|His parents ___ with him.~were~was~are|The weather ___ sunny yesterday.~was~were~is|___ the rooms clean last night?~Were~Was~Are|I ___ not tired yesterday morning.~was~were~am|We ___ away last week.~were~was~are')],
 past:['Past Simple','Use the past simple for a finished event. After did or did not, use the base form.',rows('Dana ___ a travel book yesterday.~bought~buy~buys|They ___ lunch at a restaurant last Saturday.~had~have~has|Did she ___ any photos?~take~took~takes|We did not ___ by bus yesterday.~go~went~goes|Kim ___ her friend last weekend.~met~meet~meets|What time did they ___ home?~walk~walked~walks')],
 compare:['Comparatives and superlatives','Use a comparative plus than to compare two things. Use the plus a superlative to compare one thing with a whole group.',rows('The red bag is ___ than the blue one.~lighter~lightest~light|This is the ___ laptop in the shop.~cheapest~cheaper~cheap|My new desk is ___ than my old one.~bigger~biggest~big|Model B has a ___ battery than Model A.~better~best~good|This is the ___ interesting book in the library.~most~more~much|The train is faster ___ the bus.~than~then~that')],
 'going-to':['be going to','Use am, is or are going to plus a base verb for a plan made before speaking.',rows('Rosa ___ going to have a picnic.~is~are~am|We are going to ___ six friends.~invite~invites~inviting|I ___ going to bring juice.~am~is~are|___ they going to meet at eleven?~Are~Do~Does|Her brother is not going to ___ tea.~make~makes~making|What are you going to ___ tomorrow?~do~does~doing')],
 questions:['Questions in context','Use the correct question word and auxiliary. Where asks about place, when about time, and how long about duration.',rows('___ do classes start? At six.~When~Where~Who|___ do you practise? For twenty minutes.~How long~How many~Who|___ does Maya study? At Orbit.~Where~Who~Whose|___ she like listening tasks?~Does~Do~Is|___ days does she study? Monday and Wednesday.~Which~Who~Whose|___ is your teacher? Anna.~Who~Where~When')],
 perfect:['Present Perfect','Use have or has plus a past participle for an experience or a result connected to now. Use the past simple with a finished past time.',rows('Sara has ___ three countries.~visited~visit~visits|Have you ___ tried sailing?~ever~yet~since|She has not booked a hotel ___.~yet~already~ever|I ___ never climbed a mountain.~have~has~am|She ___ to Italy last summer.~went~has gone~go|They have ___ bought a guidebook.~already~yet~since')],
 'past-continuous':['Past Continuous','Use was or were plus the ing form for an action in progress at a past time. A short past simple event can interrupt it.',rows('I ___ walking home when I heard a noise.~was~were~am|The dog was ___ near a shop.~standing~stand~stood|While I ___ calling, the owner arrived.~was~were~am|They ___ waiting when the bus came.~were~was~are|What ___ you doing at eight yesterday?~were~was~are|It started to rain while we were ___.~walking~walk~walked')],
 future:['Plans, arrangements and predictions','Use the present continuous for a confirmed arrangement, going to for an intention, and will for a prediction or a decision made now.',rows('We ___ visiting the museum on Friday; it is booked.~are~is~am|I think the weather ___ be fine tomorrow.~will~is~has|Look at those clouds. It is going to ___.~rain~rains~raining|The phone is ringing. I ___ answer it.~will~am~have|We have bought tickets. We ___ flying on Monday.~are~will~have|I am going to ___ a packed lunch.~take~takes~taking')],
 quantifiers:['much / many / a little / a few','Use many and a few with plural countable nouns. Use much and a little with uncountable nouns.',rows('We need a ___ carrots for the soup.~few~little~much|Do not add too ___ salt.~much~many~few|There is a ___ water in the bottle.~little~few~many|How ___ people are coming?~many~much~little|There is not ___ bread left.~much~many~few|We have enough ___ for four people.~food~foods~a food')],
 advice:['should / must / have to','Use should for advice. Must not expresses a prohibition. Do not have to means something is not necessary.',rows('You ___ take regular breaks. It is good advice.~should~should to~shoulds|You must not ___ too much medicine.~take~takes~taking|He ___ to return if he feels worse.~has~have~having|You do not have to ___ a uniform here.~wear~wears~wearing|___ I drink more water?~Should~Should to~Do should|She should ___ a doctor if the pain continues.~see~sees~seeing')],
 gerunds:['Verb patterns','Use the ing form after enjoy and mind. Use to plus a base verb after want, decide, hope, offer and manage.',rows('Zara enjoys ___ in her free time.~drawing~to draw~draw|She has decided ___ an online course.~to take~taking~take|Her friend offered ___ her.~to help~helping~help|Do you mind ___ the window?~opening~to open~open|She hopes ___ a poster next month.~to make~making~make|We managed ___ the work on time.~to finish~finishing~finish')],
 relative:['who / which / where','Use who for people, which for things and where for places in defining relative clauses.',rows('Lina is the volunteer ___ teaches art.~who~which~where|This is the room ___ visitors study.~where~who~which person|The centre has a garden ___ is open to everyone.~which~who~where|People ___ live nearby can join.~who~which~where|This is the project ___ we started last year.~which~who~where|The person ___ ideas we discussed is our mentor.~whose~which~where')],
 'first-conditional':['First Conditional','Use if plus the present simple, followed by will plus a base verb, for a real future possibility.',rows('If the weather ___ good, we will meet at nine.~is~will be~was|If it rains, we ___ go on Sunday.~will~would~are|We will leave when the park ___ clean.~is~will be~was|If everyone helps, we will ___ early.~finish~finished~finishes|If you ___ water, you will have something to drink.~bring~will bring~brought|We will not start unless the teacher ___.~arrives~will arrive~arrived')],
 passive:['Present Simple passive','Use am, is or are plus a past participle when the receiver of an action is the main focus.',rows('The bags ___ made from recycled cotton.~are~is~do|The fabric is ___ before it is cut.~checked~check~checking|Every bag ___ tested before packing.~is~are~does|The bags are ___ to local shops.~delivered~deliver~delivering|English ___ spoken in many countries.~is~are~does|These chairs are ___ from wood.~made~make~making')],
 obligation:['Obligation and necessity','Use have to for an obligation. Use do not have to when something is not necessary. Use must not for something prohibited.',rows('Omar ___ to arrive before his shift.~has~have~having|He does not have to ___ a uniform.~wear~wears~wearing|___ you have to work on Sundays?~Do~Does~Are|Staff must not ___ customer passwords.~share~shares~sharing|You do not ___ to bring your own pen.~have~has~having|Does she ___ to attend the training?~have~has~having')],
 'review-a2':['A2 review','Choose a tense or verb form that fits the time and meaning. Check both the auxiliary and the main verb.',rows('Ella ___ lessons every Friday.~downloads~download~downloading|Last week she ___ her password.~forgot~forgets~has forgotten|She has ___ used this app before.~never~yet~since|She checks links before ___ them.~opening~to open~open|If she needs help, she ___ ask the administrator.~will~would~did|Her password must not be ___.~shared~share~sharing')],
 'perfect-contrast':['Present Perfect or Past Simple','Use the present perfect for a period continuing until now. Use the past simple with a finished past time such as last year.',rows('Mina has lived here ___ four years.~for~since~ago|She ___ an award last year.~won~has won~wins|She has ___ completed two projects.~already~yet~since|Mina moved to the city four years ___.~ago~since~for|She has not found a full-time job ___.~yet~already~ever|___ you ever worked as a volunteer?~Have~Did~Are')],
 'past-perfect':['Past Perfect','Use had plus a past participle for an event that happened before another past event.',rows('The passengers ___ left before the reporter arrived.~had~have~were|The company had ___ replacement buses.~arranged~arrange~arranging|By the time I got there, the meeting had ___.~finished~finish~finishing|She checked the information after she ___ spoken to a witness.~had~has~was|They had not ___ the early post.~seen~saw~see|___ the manager confirmed the story before publication?~Had~Has~Was')],
 'second-conditional':['Second Conditional','Use if plus a past form, followed by would plus a base verb, for an imagined present or future situation.',rows('If Daniel accepted, he ___ live further away.~would~will~is|If I ___ more time, I would volunteer.~had~have~will have|She would move if the rent ___ lower.~were~will be~is being|If you worked remotely, would you ___ the job?~accept~accepted~accepting|I would not buy it if it ___ too expensive.~were~will be~is being|What ___ you do if you had a free year?~would~will~are')],
 'passive-b1':['Passive forms','Choose the tense of be, then use the past participle. The time expression tells you which tense is needed.',rows('The prototype was ___ last year.~tested~test~testing|A new filter has been ___ by the team.~developed~develop~developing|The device will be ___ locally next year.~produced~produce~producing|The system is ___ by sunlight.~powered~power~powering|The first models ___ built in 2024.~were~was~are|Water is ___ using a special membrane.~cleaned~clean~cleaning')],
 reported:['Reported speech','When reporting a past conversation, tenses often move back. Will becomes would, can becomes could, and a reported question uses statement word order.',rows('She said the office ___ close early.~would~will to~is to be|Leo asked whether the team ___ work from home.~could~can to~was|She explained that the building ___ repairs.~needed~need~needing|The manager reminded us ___ our files.~to save~saving~save|He asked where the meeting ___.~was~was it~is it|She said she ___ sent a written summary.~had~has been~was')],
 deduction:['Modals of deduction','Use must for a strong conclusion, might for a possibility, and cannot for something you believe is impossible. For past events use have plus a past participle.',rows('The tea is warm. She must have ___ recently.~left~leave~leaving|She ___ be next door; I am not sure.~might~must to~cannot to|Her phone is on the desk. She cannot have ___ it.~taken~took~take|He worked all night. He must ___ exhausted.~be~to be~being|The door is locked. They might have ___ home.~gone~went~go|That cannot ___ Mia; she is abroad.~be~to be~being')],
 'relative-b1':['Defining and non-defining clauses','Use commas for extra information in non-defining clauses. Do not use that after a comma. Use whose to show possession.',rows('My mentor, ___ runs a studio, is very supportive.~who~that~which|The project ___ we finished won an award.~that~who~where|This is the office ___ we meet every Friday.~where~which person~who|A colleague ___ ideas I admire has joined us.~whose~who~which|The studio, ___ opened last year, is growing.~which~that~where|The people ___ helped us were volunteers.~who~which~where')],
 'perfect-continuous':['Present Perfect Continuous','Use have or has been plus the ing form to focus on an activity continuing or repeated up to now. Use the simple form to emphasise completed results.',rows('We have been ___ the festival for six weeks.~preparing~prepare~prepared|Ada ___ been designing posters all morning.~has~have~is|I have ___ three artists today; the calls are finished.~contacted~been contact~contact|How long ___ you been working on this?~have~has~are|More volunteers have been ___ us lately.~joining~join~joined|She has been studying ___ Monday.~since~for~ago')],
 'future-b1':['Future forms in context','Use the right future form for arrangements, intentions, predictions and schedules. Be due to describes a scheduled event.',rows('Construction is due ___ in March.~to start~starting~start|The city is ___ to build a new tram line.~going~will~about|I think the tram ___ reduce traffic.~will~is~has|We ___ meeting the engineers tomorrow; it is arranged.~are~will~have|The bus is about ___; hurry up.~to leave~leaving~leave|The first section should ___ ready by winter.~be~to be~being')],
 'verb-patterns':['Verb patterns and meaning','An ing form or an infinitive can change the meaning. Remember to do means not to forget a task. Stop doing means to end an activity.',rows('Noor decided ___ a colleague for feedback.~to ask~asking~ask|The colleague suggested ___ the opening shorter.~making~to make~make|She remembered ___ the report before sending.~to attach~attaching to~attach|He stopped ___ his phone so he could concentrate.~checking~to checking~check|They managed ___ the problem clearly.~to explain~explaining~explain|Would you mind ___ this paragraph?~reading~to read~read')],
 connectors:['Linking ideas','Although introduces a clause, despite takes a noun or ing form, and however links contrasting statements. In order to introduces a purpose.',rows('___ extra hours cost money, volunteers can help.~Although~Despite~However of|The plan is useful. ___, it needs more funding.~However~Although~Despite|They will run a trial in order ___ evidence.~to collect~collecting~collect|___ the extra cost, they want to try the idea.~Despite~Although~However|Staff are needed ___ the library can operate safely.~so that~in order to~despite|The trial was successful; ___, they extended it.~therefore~although~despite')],
 'review-b1':['B1 review','Use time, context and meaning to decide. Notice completed results, ongoing activities, reported ideas and imagined situations.',rows('Amir has been ___ a speaking diary for a month.~keeping~keep~kept|His teacher suggested ___ twice a week.~practising~to practise~practise|If he had more time, he ___ practise daily.~would~will~is|The first recording was ___ in January.~made~make~making|He said he ___ noticed clearer pronunciation.~had~has been~was|___ the course has ended, he will keep learning.~Although~Despite~However of')]
};

const rotate=(values,n)=>[...values.slice(n),...values.slice(0,n)];
const hashNumber=s=>[...s].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);
function choose(prompt,correct,others,seed,extra={}){const options=rotate([correct,...others],hashNumber(seed)%3);return {type:'choice',prompt,options,answer:options.indexOf(correct),explanation:`${prompt.replace('___',correct)}${prompt.includes('___')?'':` — ${correct}`}`,...extra};}
function buildUnit(level,index,part,c){
 const code=`${index+1}.${part+1}`,id=level+'-'+code,[focus,rule,bank]=grammar[c.topic],lexicon=c.words.slice(part*8,part*8+8),phase=['Words & forms','In context','Skills & review'][part],facts=rotate(c.facts,part*2),forms=rotate(bank,part*2);
 const vocabulary=lexicon.map((w,i)=>choose(`Выбери перевод: ${w.word}`,w.meaning,[c.words[(part*8+i+9)%24].meaning,c.words[(part*8+i+17)%24].meaning],id+'v'+i,{word:w.word}));
 const vocabInput=lexicon.slice(0,6).map(w=>({type:'text',prompt:`Напиши английское слово или выражение: «${w.meaning}».`,answers:[w.word],hint:w.word[0],explanation:`${w.word} — ${w.meaning}.`}));
 const formQuestions=forms.map((r,i)=>choose(r.sentence,r.correct,r.other,id+'g'+i,{explanation:rule+' '+r.sentence.replace('___',r.correct)}));
 const order=forms.slice(0,4).map((r,i)=>{const answer=r.sentence.replace('___',r.correct);return {type:'order',prompt:'Собери правильное предложение.',tokens:rotate(answer.replace(/[.!?]$/,'').split(' '),2+i),answers:[answer],explanation:rule};});
 const gaps=forms.slice(0,4).map(r=>({type:'text',prompt:r.sentence,answers:[r.correct],hint:r.correct[0],explanation:rule+' '+r.sentence.replace('___',r.correct)}));
 const storyQuestions=(offset,count)=>facts.slice(offset,offset+count).map(([prompt,correct,...other],i)=>choose(prompt,correct,other,id+'r'+offset+i,{explanation:`${correct} Ответ находится в истории этого юнита.`}));
 const examples=forms.slice(0,3).map(r=>r.sentence.replace('___',r.correct));
 const narration=`Welcome to Orbit. ${c.title}. Our focus is ${focus}. ${rule} Listen to these examples. ${examples.join(' ')} Pause the video and say one example aloud. Now practise the vocabulary and complete the tasks. You can try again and learn from every answer.`;
 const videoQuestions=[choose('Что отрабатываем в этом видео?',focus,[grammar[level==='A1'?'perfect':'be'][0],grammar[level==='B1'?'there':'reported'][0]],id+'video1',{explanation:rule}),choose('Выбери предложение из объяснения.',examples[0],[forms[0].sentence.replace('___',forms[0].other[0]),forms[0].sentence.replace('___',forms[0].other[1])],id+'video2',{explanation:rule})];
 const intro=`${c.title} / ${phase}.\n${rule}\n\n${examples.join('\n')}`;
 const steps=[
  {type:'vocabulary',skill:'vocabulary',title:'Vocabulary',instructions:'Изучи слова: послушай произношение, проверь перевод, затем выполни проверку.',words:lexicon,questions:vocabulary},
  {type:'video',skill:'grammar',title:focus, instructions:intro,mediaUrl:'',transcript:narration,questions:videoQuestions},
  {type:'practice',skill:'vocabulary',title:'Word builder',instructions:'Task 1 · Вспомни слово по переводу. Первая буква дана как подсказка.',questions:vocabInput},
  {type:'practice',skill:'grammar',title:'Choose the right form',instructions:'Task 2 · Выбери подходящую форму, чтобы заполнить пропуск.',questions:formQuestions},
  {type:'practice',skill:'grammar',title:'Put it together',instructions:'Task 3 · Нажимай на слова по порядку и собери предложение.',questions:order},
  {type:'reading',skill:'reading',title:'Read the story',instructions:c.story,questions:storyQuestions(0,3)},
  {type:'listening',skill:'listening',title:'Listen for detail',instructions:'Task 5 · Послушай историю и ответь на вопросы. Запись можно прослушать ещё раз.',mediaUrl:'',transcript:c.story,questions:storyQuestions(3,3)},
  {type:'practice',skill:'grammar',title:'Complete the gaps',instructions:'Task 6 · Введи пропущенное слово или выражение.',questions:gaps}
 ];
 return {id,level,code,title:c.title+' · '+phase,edition:'ORBIT Original Practice · 2026',focus,rule,examples,narration,story:c.story,steps:steps.map(s=>({mediaUrl:'',...s})),total:steps.reduce((n,s)=>n+s.questions.length,0)};
}
export const courseUnits=Object.entries(chapters).flatMap(([level,list])=>list.flatMap((c,i)=>[0,1,2].map(p=>buildUnit(level,i,p,c))));
